# R script to generate alpha rarefaction curve plots
# Input: alpha rarefaction data csv file generated by qiime diversity alpha-rarefaction
# By Yewei on 2024.4.12

log <- file(snakemake@log[[1]], open="wt")
sink(log)
sink(log, type="message")

library(reshape2)
library(dplyr)
library(ggplot2)
library(RColorBrewer)
library(glue)
library(vegan)
library(tidyverse)

# Input
otu_table <- read_tsv(snakemake@input[["otu_table"]], skip = 1) %>%
  column_to_rownames("#OTU ID") %>%
  as.matrix() %>%
  t()

metadata <- read_tsv(snakemake@params[["metadata"]]) %>% 
  select(SampleID, Group)

metric <- snakemake@wildcards[["metric"]]
metric_name <- ifelse(
  metric == "observed_features", "Observed Features",
  ifelse(metric == "shannon", "Shannon Index", "")
)

contrast <- snakemake@wildcards[["contrast"]]

rarefaction_step <- 200

# Function to generate observed_features rarefaction curve data frame
observed_features_data <- function(otu_table, metadata, step = 100) {
  # use vagan::rarecurve() to calculate rarefaction curve data\
  pdf(NULL)
  rare_result <- rarecurve(
    otu_table,
    step = 100,
    sample = 1,
    tidy = TRUE
  ) %>%
    dplyr::rename(SampleID = Site, Depth = Sample, Richness = Species) %>% 
    dplyr::select(SampleID, Depth, Richness)
  dev.off()

  # add (0,0)
  zero_points <- rare_result %>%
    dplyr::distinct(SampleID) %>%
    dplyr::mutate(Depth = 0, Richness = 0)

  full_rare_data <- bind_rows(zero_points, rare_result) %>%
    dplyr::arrange(SampleID, Depth)

  # merge with metadata
  rare_with_metadata <- full_rare_data %>%
    dplyr::left_join(metadata, by = "SampleID")

  return(rare_with_metadata)
}

# Function to generate shannon rarefaction curve data frame
shannon_data <- function(otu_table, metadata, step = 100, n_iter = 1) {
  max_depth <- max(rowSums(otu_table))
  depths <- seq(0, max_depth, step)
  results <- list()
  
  for (depth in depths) {
    otu_table_tmp <- otu_table[names(rowSums(otu_table)[rowSums(otu_table) >= depth]), , drop = FALSE]
    shannon_values <- c()
    
    for (iter in 1:n_iter) {
      rarefied <- rrarefy(otu_table_tmp, depth)
      shannon <- diversity(rarefied, index = "shannon", base = 2)
      shannon_values <- c(shannon_values, shannon)
    }
    
    for (i in 1:nrow(otu_table_tmp)) {
      sample_name <- rownames(otu_table_tmp)[i]
      iter_shannon <- shannon_values[seq(i, length(shannon_values), by = nrow(otu_table_tmp))]
      
      results[[length(results) + 1]] <- data.frame(
        SampleID = sample_name,
        Depth = depth,
        Richness = mean(iter_shannon),
        SE = sd(iter_shannon),
        Iteration = iter
      )
    }
  }
  
  results_df <- bind_rows(results)

  rare_with_metadata <- results_df %>%
    dplyr::select(SampleID, Depth, Richness) %>% 
    dplyr::left_join(metadata, by = "SampleID")

  smoothed_shannon <- rare_with_metadata %>%
    dplyr::group_by(SampleID) %>%
    dplyr::arrange(Depth) %>%
    dplyr::mutate(log_depth = log(Depth + 1) ) %>%
    dplyr::mutate(
      Richness_smooth = predict(loess(Richness ~ log_depth, span = 0.9))
    ) %>%
    dplyr::ungroup() %>% 
    dplyr::select(-Richness) %>% 
    dplyr::rename(Richness = Richness_smooth)

  smoothed_shannon$Richness <- ifelse(smoothed_shannon$Depth == 0, 0, smoothed_shannon$Richness)

  return(smoothed_shannon)
}

# Generate alpha rarefaction curve plots
if (snakemake@wildcards[["contrast"]] == "all") {
  if (metric == "observed_features") {
    plot_df <- observed_features_data(otu_table, metadata, step = rarefaction_step)
  } else if (metric == "shannon") {
    plot_df <- shannon_data(otu_table, metadata, step = rarefaction_step)
  }

  # Output to a table
  plot_out_df <- plot_df %>%
    dplyr::select(SampleID, Group, Depth, Richness) %>%
    rename(Sample = SampleID, Group = Group, Seqs_sampled = Depth, Value = Richness)
  write.table(
    plot_out_df, 
    file = snakemake@output[["xls"]],
    row.names = FALSE, 
    col.names = TRUE, 
    quote = FALSE, 
    sep = "\t"
  )

  # Color palette
  if (snakemake@params[["color"]] == "sample") {
    color_count <- length(unique(plot_df$SampleID))
  } else if (snakemake@params[["color"]] == "group") {
    color_count <- length(unique(plot_df$Group))
  }
  color_pal <- brewer.pal(n = 8, "Set1")
  if (color_count <= 8) {
    get_palette = colorRampPalette(color_pal[1:color_count])
  } else {
    get_palette = colorRampPalette(color_pal)
  }

  # Make plots and output
  if (snakemake@params[["color"]] == "sample") {
    p <- ggplot(plot_df, aes(x=Depth, y=Richness, color=SampleID))
    point_size_value <- 1
    line_size_value <- 0.6
    alpha_value <- 0.8
    color_legend_title <- "Sample"
  } else if (snakemake@params[["color"]] == "group") {
    p <- ggplot(plot_df, aes(x=Depth, y=Richness, color=Group))
    point_size_value <- 1
    line_size_value <- 0.6
    alpha_value <- 0.4
    color_legend_title <- "Group"
  }

  p <- p + 
    geom_point(size = point_size_value, alpha = alpha_value) +
    geom_line(
      aes(group = SampleID), 
      linewidth = line_size_value, 
      alpha = alpha_value
    ) +
    scale_color_manual(values = get_palette(color_count)) +
    theme_bw() +
    theme(
      plot.title = element_text(face = "bold", hjust = 0.5),
      axis.title = element_text(face = "bold"),
      axis.text = element_text(face = "bold"),
      legend.title = element_text(face = "bold")
    ) +
    labs(
      title = glue("Rarefaction Curves of {metric_name}: {contrast}"), 
      x = "Number of sequences sampled",
      y = metric_name,
      color = color_legend_title
    ) + 
    guides(color = guide_legend(override.aes = list(alpha = 1)))

  ggsave(
    filename = snakemake@output[["pdf"]],
    plot = p,
    width = 10,
    height = 9
  )
  ggsave(
    filename = snakemake@output[["png"]],
    plot = p,
    width = 10,
    height = 9
  )
} else {
  group_list <- unlist(strsplit(contrast, "-vs-"))
  
  metadata <- metadata %>% 
    dplyr::filter(Group %in% group_list)
  sample_list <- metadata$SampleID

  otu_table <- otu_table[rownames(otu_table) %in% sample_list, , drop = FALSE]

  if (metric == "observed_features") {
    plot_df <- observed_features_data(otu_table, metadata, step = rarefaction_step)
  } else if (metric == "shannon") {
    plot_df <- shannon_data(otu_table, metadata, step = rarefaction_step)
  }

  thresholds <- plot_df %>%
    group_by(Group, Depth) %>%
    summarise(all_have_richness = n_distinct(SampleID) == n_distinct(plot_df$SampleID[plot_df$Group == first(Group)]), 
              .groups = 'drop_last') %>%
    filter(all_have_richness) %>%
    summarise(threshold = max(Depth), .groups = 'drop')

  plot_df <- plot_df %>%
    dplyr::select(-SampleID) %>%
    dplyr::group_by(Group, Depth) %>%
    summarise(
      mean_value = mean(Richness), 
      se_richness = sd(Richness) / sqrt(n()),
      .groups = 'drop'
    ) %>%
    left_join(thresholds, by = "Group") %>%
    filter(Depth <= threshold) %>%
    dplyr::select(-threshold)

  # Output to a table
  plot_out_df <- plot_df %>%
    dplyr::select(Group, Depth, mean_value) %>%
    rename(Group = Group, Seqs_sampled = Depth, Value = mean_value)
  write.table(
    plot_out_df, 
    file = snakemake@output[["xls"]],
    row.names = FALSE, 
    col.names = TRUE, 
    quote = FALSE, 
    sep = "\t"
  )

  # Color palette
  color_count <- length(unique(plot_df$Group))
  color_pal <- brewer.pal(n = 8, "Set1")
  if (color_count <= 12) {
    get_palette = colorRampPalette(color_pal[1:color_count])
  } else {
    get_palette = colorRampPalette(color_pal)
  }

  p <- ggplot(plot_df, aes(x = Depth, y = mean_value, color = Group)) +
    geom_ribbon(
      aes(
        ymin = mean_value - 1.96 * se_richness, 
        ymax = mean_value + 1.96 * se_richness, 
        fill = Group
      ), 
      color = NA, 
      alpha = 0.1
    ) +
    geom_point(size = 1) +
    geom_line(linewidth = 0.6) +
    scale_color_manual(values = get_palette(color_count)) +
    scale_fill_manual(values = get_palette(color_count), guide = "none") +
    theme_bw() +
    theme(
      plot.title = element_text(face = "bold", hjust = 0.5),
      axis.title = element_text(face = "bold"),
      axis.text = element_text(face = "bold"),
      legend.title = element_text(face = "bold")
    ) +
    labs(
      title = glue("Rarefaction Curves of {metric_name}: {contrast}"),
      x = "Number of sequences sampled",
      y = metric_name,
      color = "Group"
    )

  ggsave(
    filename = snakemake@output[["pdf"]],
    plot = p,
    width = 10,
    height = 9
  )
  ggsave(
    filename = snakemake@output[["png"]],
    plot = p,
    width = 10,
    height = 9
  )
}